<div><form wire:submit="save"><input wire:model="vendor_name" placeholder="Vendor"><input wire:model="contract_number" placeholder="Contract number"><input wire:model="title" placeholder="Contract title"><input wire:model="start_date" type="date"><input wire:model="end_date" type="date"><button type="submit">Create contract</button></form><ul>@forelse($contracts as $contract)<li>{{ $contract->vendor_name }} — {{ $contract->title }} ({{ $contract->status }}, ends {{ $contract->end_date }}) @if ($contract->status === 'draft')<button type="button" wire:click="transition({{ $contract->id }}, 'active')">Activate</button>@elseif ($contract->status === 'active')<button type="button" wire:click="transition({{ $contract->id }}, 'terminated')">Terminate</button>@endif <button type="button" wire:click="delete({{ $contract->id }})">Delete</button></li>@empty<li>No vendor contracts yet.</li>@endforelse</ul></div>
